// Handle both $json.body.x and $json.x depending on n8n webhook version
const src = $json.body && $json.body.message !== undefined ? $json.body : $json;

const user_message     = (src.message     || '').trim();
const conversation_id  =  src.conversation_id || 'default';
const history          = Array.isArray(src.history) ? src.history : [];

return [{ json: { user_message, conversation_id, history } }];

// Fetch Tracker HTML now calls /api/context which returns JSON:
// { data: "combined project text", project_count: N, projects: [...] }
const resp     = $input.first().json;
const upstream = $('Extract Fields').first().json;

// Get combined project text (may be nested under 'data' or direct)
const contextText = resp.data || resp.body?.data || '';
const projectList = resp.projects || resp.body?.projects || [];

return [{ json: {
  html:           contextText,
  project_count:  resp.project_count || projectList.length || 0,
  projects:       projectList,
  user_message:   upstream.user_message,
  conversation_id:upstream.conversation_id,
  history:        upstream.history || []
}}];

const item = $input.first().json;
const history = Array.isArray(item.history) ? item.history : [];

// System prompt — grounded, scoped, ≤3 sentences
const systemPrompt =
  `You are a project assistant for the AI PM Tool. ` +
  `Answer ONLY based on the project data provided below. ` +
  `If information is not in the data, say "I don't have that information in the current tracker." ` +
  `Never guess or fabricate step data or dates. ` +
  `Keep answers under 3 sentences unless the user explicitly asks for a list. ` +
  `Politely decline any question outside project status, steps, DRI assignments, deadlines, milestones, or dependencies.\n\n` +
  `Project Data (today: ${new Date().toISOString().split('T')[0]}):\n` +
  item.project_context;

// Messages array for Claude API — history + current user turn
const userMsg = (item.user_message || '').trim() || 'Hello';
const messages = [
  ...history,
  { role: 'user', content: userMsg }
];

// Return as object (not stringified) so HTTP Request node can send it as JSON
return [{
  json: {
    conversation_id: item.conversation_id,
    project_context: item.project_context,
    request_body: {
      model: 'claude-sonnet-4-6',
      max_tokens: 300,
      system: systemPrompt,
      messages
    }
  }
}];

const api = $input.first().json;

// Extract reply text from Anthropic response envelope
const reply =
  api.content && api.content[0] && api.content[0].text
    ? api.content[0].text
    : 'Sorry, I could not generate a response. Please try again.';

return [{
  json: {
    reply,
    sources:   ['tracker.html'],
    model:     api.model || 'claude-sonnet-4-6',
    timestamp: new Date().toISOString()
  }
}];
